class TextString
{
public:
    virtual ~TextString();
};

class FEGraphicalMenu
{
    char state[0x16c];

public:
    virtual ~FEGraphicalMenu();
};

class OptionsMenu : public FEGraphicalMenu
{
    enum
    {
        OpStereoEntry = 5,
        OpEnd = 11,
        MAX_VOLUME = 10,
        NUM_VOLUME = 5,
        num_switches = OpStereoEntry
    };

    void *levels[NUM_VOLUME][MAX_VOLUME];
    void *lights[OpEnd];
    void *back;
    float rumbleTimer[4];
    int stereo_op;
    TextString *stereo_text[3];
    TextString *switch_text[num_switches][2];
    TextString *options_text;
    TextString *slevels_text;

public:
    virtual ~OptionsMenu();
};

__asm__(".equ _$_15FEGraphicalMenu, 0x001DAF70");

OptionsMenu::~OptionsMenu()
{
	for(int i=0; i<num_switches; i++)
	{
		if(i < 3) delete stereo_text[i];
		delete switch_text[i][0];
		delete switch_text[i][1];
	}
	delete options_text;
	delete slevels_text;
}
